        console.warn(`Invalid due date at row ${i + 2}: ${dueValue}`);
        return;
      }
    } else {
      console.warn(`Missing due date at row ${i + 2}`);
      return;
    }

    const subject = 'Missing assignment: ' + assignment;
    const body = 'Hi ' + name + ', our records show that ' + assignment +
      ' (due ' + due + ') has not been turned in yet. Please submit it this week ' +
      'or come see me during office hours.';

    MailApp.sendEmail({
      to: studentEmail,
      cc: parentEmail,
      subject: subject,
      body: body
    });

    // Mark row as sent
    sheet.getRange(i + 2, 6).setValue(new Date());
  });
}
```

### Important for the emails already sent

Your previous run sent some emails without marking them, so before you run this updated script, go through the rows that already received a reminder and put something in column F — like `Yes` or a date. Otherwise those students will get a duplicate.

If the script was processing rows in order and crashed on a bad date, you can usually mark all rows above the bad-date row as sent. If you’re not sure, check your Gmail Sent folder to identify which reminders went out.
